```groovy
import com.atlassian.jira.issue.Issue;
import com.atlassian.jira.issue.IssueManager;
import com.atlassian.jira.project.Project;
import com.atlassian.jira.project.ProjectManager;

def issue = context.getIssue();
def project = context.getProject();
def issueManager = project.getIssueManager();

// Get all checklist items for the current issue
def checklistItems = issue.getCustomFieldValues("Checklist Item");

// Check if all checklist items are marked as done
if (checklistItems.every { it.getValue() == "done" }) {
    // If all checklist items are done, block the issue from moving to the next column
    issueManager.createComment(issue, "All checklist items are done. The issue cannot be moved to the next column.");
}
