    // Acquire both chopsticks
    get_chopstick(philosopher);
    get_chopstick(philosopher);

    // Eat
    console.log(`Philosopher ${philosopher} is eating.`);

    // Release both chopsticks
    release_chopstick(philosopher);
    release_chopstick(philosopher);
}

function wait(philosopher) {
    // Block until a chopstick becomes available
    while (!get_chopstick(philosopher)) {
        console.log(`Philosopher ${philosopher} is waiting for a chopstick.`);
    }
}
```

