import { createAccessPermissionsGuard } from './guards/access-permissions.guard';
import { Permission } from './models/permission.model';

async function bootstrap() {
  const app = await NestFactory.create(AppModule);

  const guard = createAccessPermissionsGuard([
    new Permission('read', 'users'),
    new Permission('write', 'users'),
    new Permission('read', 'posts'),
    new Permission('write', 'posts'),
  ]);

  app.useGlobalGuards(guard);

  await app.listen(3000);
}

bootstrap();
```

