```javascript
function getEntriesByKey(object, key) {
  const keys = key.split(".");
  let result = [];

  function recurse(obj, path) {
    if (path === keys.length) {
      result.push(obj);
      return;
    }

    const key = keys[path];
    obj[key] && recurse(obj[key], path + 1);
  }

  recurse(object, 0);
  return result;
}
