Here's an example of a React hook that converts temperatures between Celsius, Fahrenheit, and Kelvin:

```javascript
import { useState } from 'react';

function useTemperatureConverter() {
  const [temperature, setTemperature] = useState(0);
  const [unit, setUnit] = useState('celsius');

  const handleConvert = (e) => {
    e.preventDefault();

    if (unit === 'celsius') {
      setTemperature((temperature * 1.8) + 32);
      setUnit('fahrenheit');
    } else if (unit === 'fahrenheit') {
      setTemperature(((temperature - 32) / 1.8));
      setUnit('celsius');
    } else if (unit === 'kelvin') {
      setTemperature(temperature - 273.15);
      setUnit('celsius');
    }
  };

  return { temperature, unit, handleConvert };
}

export default useTemperatureConverter;
```

To use this hook in your component, simply import it and call the `useTemperatureConverter` function:

```javascript
import React from 'react';
import useTemperatureConverter from './useTemperatureConverter';

const TemperatureConverter = () => {
  const { temperature, unit, handleConvert } = useTemperatureConverter();

  return (
    <div>
      <h2>Temperature Converter</h2>
      <p>Current temperature: {temperature} {unit}</p>
      <form onSubmit={handleConvert}>
        <button type="submit">Convert</button>
      </form>
    </div>
  );
};

export default TemperatureConverter;
```

This component allows you to switch between Celsius, Fahrenheit, and Kelvin units and convert temperatures between them.

