// ParseStruct parses the given Go struct and returns its fields.
func ParseStruct(structName string) ([]string, error) {
	file, err := ioutil.ReadFile(fmt.Sprintf("%s.go", structName))
	if err != nil {
		return nil, err
	}

	parts := strings.Split(string(file), "\n")
	var fields []string

	for _, part := range parts {
		if part == "" || strings.HasPrefix(part, "//") {
			continue
		}

		fields = append(fields, part)
	}

	return fields, nil
}

// GenerateAvroSchema generates the Avro schema based on the given fields.
func GenerateAvroSchema(fields []string) string {
	schema := "{"

	for _, field := range fields {
		fieldType := reflect.TypeOf(field).String()
		fieldName := reflect.ValueOf(field).String()

		schema += fmt.Sprintf("\"%s\": {\"type\": \"%s\", \"name\": \"%s\"}, ", fieldName, fieldType, fieldName)
	}

	schema = strings.TrimSuffix(schema, ", ")
	schema += "}"

	return schema
}

