To retrieve the username from the JWT token in ASP.NET Core Web API, you can use the `ClaimsPrincipal` class and the `User` property. Here's a step-by-step guide:

1. First, make sure you have installed the `Microsoft.IdentityModel.Tokens` package using NuGet. This package provides the necessary classes to work with JWT tokens.

2. In your WebApi project, create a new class called `JwtService` that will handle the JWT token validation and retrieval of the username.

```csharp
using Microsoft.IdentityModel.Tokens;
using System.Security.Claims;
using System.Security.Cryptography;
using System.Text;

public class JwtService
{
    private readonly string _secretKey;

    public JwtService(string secretKey)
    {
        _secretKey = secretKey;
    }

    public ClaimsPrincipal ValidateToken(string token)
    {
        var tokenHandler = new JwtSecurityTokenHandler();
        var key = Encoding.UTF8.GetBytes(_secretKey);
        var tokenValidationParameters = new TokenValidationParameters
        {
            IssuerSigningKey = key,
            ValidateIssuer = false,
            ValidateAudience = false,
            ValidateLifetime = true,
            ValidateIssuerSigningKey = true
        };

        try
        {
            var securityToken = tokenHandler.ReadJwtToken(token, tokenValidationParameters);
            return new ClaimsPrincipal(securityToken.Claims);
        }
        catch (Exception)
        {
            return null;
        }
    }

    public string GetUsername(ClaimsPrincipal claimsPrincipal)
    {
        var userNameClaim = claimsPrincipal.FindFirst("username");
        if (userNameClaim != null)
        {
            return userNameClaim.Value;
        }
        else
        {
            return null;
        }
    }
}
```

