def is_prime(number: int) -> bool:
    """Checks if a number is prime."""
    if number <= 1:
        return False
    for i in range(2, int(number**0.5) + 1):
        if number % i == 0:
            return False
    return True

def find_maximum(numbers: list[int]) -> int:
    """Finds the maximum value in a list of numbers."""
    max_value = numbers[0]
