To create a simple toast notification using React Context, follow these steps:

1. First, let's create a `ToastContext` file to manage the toast state and provide the necessary context. Create a new file named `ToastContext.js` and add the following code:

```javascript
import { createContext, useState } from 'react';

const ToastContext = createContext();

function ToastProvider({ children }) {
  const [toast, setToast] = useState(null);

  function showToast(message) {
    setToast({ message, visible: true });
  }

  function hideToast() {
    setToast(null);
  }

  return (
    <ToastContext.Provider value={{ showToast, hideToast, toast }}>
      {children}
    </ToastContext.Provider>
  );
}

export { ToastContext, ToastProvider };
```

2. Now, let's create a component to display the toast notification. Create a new file named `Toast.js` and add the following code:

```javascript
import React from 'react';
import { useContext } from 'react';
import { ToastContext } from './ToastContext';

function Toast() {
  const { toast, showToast, hideToast } = useContext(ToastContext);

  if (!toast) {
    return null;
  }

  return (
    <div className="toast">
      <p>{toast.message}</p>
      <button onClick={hideToast}>Close</button>
    </div>
  );
}

export default Toast;
```

