To create a simple toast notification using React Context, follow these steps:

1. First, let's create a `ToastContext` file to manage the toast state and provide it as a context.

```javascript
import { createContext, useReducer } from 'react';

const initialState = {
  isOpen: false,
  message: '',
};

const toastReducer = (state, action) => {
  switch (action.type) {
    case 'SHOW_TOAST':
      return { ...state, isOpen: true, message: action.message };
    case 'HIDE_TOAST':
      return { ...state, isOpen: false, message: '' };
    default:
      return state;
  }
};

export const ToastContext = createContext(initialState);

export function ToastProvider({ children }) {
  const [state, dispatch] = useReducer(toastReducer, initialState);

  const showToast = (message) => {
    dispatch({ type: 'SHOW_TOAST', message });
  };

  const hideToast = () => {
    dispatch({ type: 'HIDE_TOAST' });
  };

  return (
    <ToastContext.Provider value={{ showToast, hideToast, ...state }}>
      {children}
    </ToastContext.Provider>
  );
}
```

2. Now, let's create a `Toast` component that will display the toast notification.

```javascript
import React from 'react';
import { useContext } from 'react';
import { ToastContext } from './ToastContext';

const Toast = () => {
  const { isOpen, message } = useContext(ToastContext);

  if (!isOpen) {
    return null;
  }

  return (
    <div className="toast">
      <p>{message}</p>
      <button onClick={() => useContext(ToastContext).hideToast()}>Close</button>
    </div>
  );
};

export default Toast;
```

