import NaturalLanguage

func rearrangePhrase(_ phrase: String) -> (sentiment: Sentiment, newPhrase: String) {
    let tagger = NLTagger(tagSchemes: [.lexicalClass])
    tagger.string = phrase
    var sentimentScore = 0.0

    let sortedLetters = phrase.filter { !$0.isWhitespace }.sorted()
    let newPhrase = String(sortedLetters)

    tagger.enumerateTags(in: phrase.startIndex..<phrase.endIndex, unit: .word, scheme: .lexicalClass) { tag, range in
        switch tag {
        case .noun:
            sentimentScore += 1.0
        case .adjective:
            if sentenceScore > 0 {
                sentimentScore -= 0.5
            } else {
                sentimentScore += 0.5
            }
        default:
            break
        }
    }

    let sentiment: Sentiment
    if sentimentScore > 0 {
        sentiment = .positive
    } else if sentimentScore < 0 {
        sentiment = .negative
    } else {
        sentiment = .neutral
    }

    return (sentiment, newPhrase)
}
```

