Here's a PowerShell script that recursively checks folders for ACLs referring to SIDs in the SIDHistory of users or groups in the domain:

```powershell
# Define the domain name and the path to start the search from
$domainName = "your_domain_name"
$startPath = "C:\path\to\start"

# Function to check if an SID is present in the SIDHistory of a user or group in the domain
function CheckSIDInSIDHistory($sid) {
    $domain = New-Object System.DirectoryServices.Domain("$domainName")
    $searcher = New-Object System.DirectoryServices.DirectorySearcher($domain)
    $searcher.Filter = "(&(objectClass=user)(objectCategory=person)(sAMAccountName=$sid))"
    $searcher.SearchScope = "Global"

    try {
        $result = $searcher.FindOne()
        if ($result) {
            return $true
        }
    } finally {
        $searcher.Dispose()
        $domain.Dispose()
    }

    return $false
}

# Function to recursively check the ACLs of folders and subfolders
function CheckACLs($path) {
    Get-ChildItem -Path $path -Directory | ForEach-Object {
        $acl = Get-Acl -Path $_.FullName
        $sidHistoryPresent = $false

        foreach ($access in $acl.Access) {
            if ($access.IdentityReference -match "^S-1-5-21-") {
                $sid = $access.IdentityReference.SubString(4)
                if (CheckSIDInSIDHistory($sid)) {
                    $sidHistoryPresent = $true
                    break
                }
            }
        }

        if ($sidHistoryPresent) {
            Write-Host "Folder: $($_.FullName)"
        }

        CheckACLs($_.FullName)
    }
}

# Start the search
CheckACLs($startPath)
```

