Here's a PowerShell script that recursively checks folders for SIDs in SIDHistory:

```powershell
# Define the function to check SIDs in SIDHistory
function CheckSIDInSIDHistory($sid) {
    $domain = (Get-ADDomain).Name
    $searcher = New-Object System.DirectoryServices.DirectorySearcher
    $searcher.Filter = "(&(objectClass=user)(sAMAccountName=$sid))"
    $searcher.PropertiesToLoad.Add("memberOf")
    $searcher.SearchScope = "Global"

    $results = $searcher.FindAll()
    foreach ($result in $results) {
        $groups = $result.GetDirectoryEntry().Properties["memberOf"]
        foreach ($group in $groups) {
            if ($group -match "^CN=(\w+)\*,OU=Security Groups,DC=$domain") {
                $sidHistory = Get-ADGroupMember -Identity $group.ToString() -Recursive | Select-Object -ExpandProperty sIDHistory
                if ($sidHistory -contains $sid) {
                    return $true
                }
            }
        }
    }

    return $false
}

# Define the function to recursively check folders
function CheckFoldersForSIDHistory($folderPath) {
    Get-ChildItem -Path $folderPath -Directory | ForEach-Object {
        $acl = Get-Acl -Path $_.FullName
        $sidHistory = $acl.Access | Where-Object {$_.IdentityReference -match "^S-1-5-21-(?<sid>\w+)"} | Select-Object -ExpandProperty sid

        if (CheckSIDInSIDHistory($sid)) {
            Write-Host "Folder: $($_.FullName) - SID: $sid is present in SIDHistory"
        }

        CheckFoldersForSIDHistory($_.FullName)
    }
}

# Call the function with the root folder path
$rootFolderPath = "C:\Your_Root_Folder_Path"
CheckFoldersForSIDHistory($rootFolderPath)
```

