# Define the function to check if an SID exists in the SIDHistory of a user or group
function CheckSidInSidHistory($sid) {
    $domain = (Get-ADDomain).Name
    $searcher = New-Object System.DirectoryServices.DirectorySearcher("LDAP://$domain")
    $searcher.Filter = "(&(objectClass=user)(objectCategory=person)(sAMAccountName=$sid))"
    $results = $searcher.FindAll()

    if ($results.Count -eq 0) {
        $searcher = New-Object System.DirectoryServices.DirectorySearcher("LDAP://$domain")
        $searcher.Filter = "(&(objectClass=group)(objectCategory=group)(sAMAccountName=$sid))"
        $results = $searcher.FindAll()
    }

    return $results.Count -gt 0
}

# Define the function to recurse through folders and check their ACLs
function CheckFoldersForInvalidSids($folderPath) {
    Get-ChildItem -Path $folderPath -Directory | ForEach-Object {
        $acl = Get-Acl -Path $_.FullName
        $invalidSids = $acl.Access | Where-Object {$_.IdentityReference -match '^S-1-5-21-'} | Where-Object {CheckSidInSidHistory($_)}

        if ($invalidSids) {
            Write-Host "Folder: $($_.Name)"
            Write-Host "Invalid SIDs found in ACL:"
            $invalidSids | ForEach-Object {Write-Host "- $_"}
        }

        CheckFoldersForInvalidSids($_.FullName)
    }
}

# Call the function with the root folder path
CheckFoldersForInvalidSids("C:\")
